 86	package com.pousada.api;
 87	
 88	import com.pousada.api.dto.CreateReservationRequest;
 89	import com.pousada.api.dto.DocumentResponse;
 90	import com.pousada.api.dto.ReservationResponse;
 91	import com.pousada.domain.*;
 92	import com.pousada.domain.rateplan.RatePlan;
 93	import com.pousada.domain.rateplan.RatePlanFactory;
 94	import com.pousada.repository.MessageRepository;
 95	import com.pousada.repository.ReservationRepository;
 96	import com.pousada.repository.RoomRepository;
 97	import com.pousada.service.DocumentService;
 98	import com.pousada.service.PricingService;
 99	import io.javalin.http.Context;
100	
101	import java.time.LocalDate;
102	import java.time.temporal.ChronoUnit;
103	
104	public class ReservationController {
105	    private final ReservationRepository reservationRepository;
106	    private final RoomRepository roomRepository;
107	    private final MessageRepository messageRepository;
108	    private final PricingService pricingService;
109	    private final DocumentService documentService;
110	
111	    public ReservationController(ReservationRepository reservationRepository,
112	                                 RoomRepository roomRepository,
113	                                 MessageRepository messageRepository,
114	                                 PricingService pricingService,
115	                                 DocumentService documentService) {
116	        this.reservationRepository = reservationRepository;
117	        this.roomRepository = roomRepository;
118	        this.messageRepository = messageRepository;
119	        this.pricingService = pricingService;
120	        this.documentService = documentService;
121	    }
122	
123	    public void createReservation(Context ctx) {
124	        try {
125	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
126	
127	            validateRequest(request);
128	
129	            Room room = roomRepository.findByNumber(request.roomNumber())
130	                .orElseThrow(() -> new ValidationException("ROOM_NOT_FOUND", "Room not found", 404));
131	
132	            if (request.guests() > room.getCapacity()) {
133	                throw new ValidationException("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity", 422);
134	            }
135	
136	            if (reservationRepository.hasConflict(request.roomNumber(), request.checkIn(), request.checkOut(), null)) {
137	                throw new ValidationException("ROOM_UNAVAILABLE", "Room is not available for the selected dates", 409);
138	            }
139	
140	            RatePlan ratePlan = RatePlanFactory.get(request.ratePlan());
141	            int nights = (int) ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
142	
143	            var subtotal = pricingService.calculateSubtotal(room.getNightlyRate(), request.checkIn(), request.checkOut());
144	            var discount = pricingService.calculateDiscount(subtotal, ratePlan);
145	            var total = pricingService.calculateTotal(subtotal, discount);
146	
147	            Reservation reservation = new Reservation(
148	                null,
149	                request.roomNumber(),
150	                request.guestName(),
151	                request.guestEmail(),
152	                request.guestCpf(),
153	                request.checkIn(),
154	                request.checkOut(),
155	                request.guests(),
156	                ratePlan,
157	                nights,
158	                subtotal,
159	                discount,
160	                total
161	            );
162	
163	            reservationRepository.save(reservation);
164	
165	            ctx.status(201).json(toResponse(reservation));
166	
167	        } catch (ValidationException e) {
168	            ctx.status(e.statusCode).json(new ErrorResponse(e.errorCode, e.message));
169	        } catch (Exception e) {
170	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
171	        }
172	    }
173	
174	    public void getReservation(Context ctx) {
175	        try {
176	            Long id = Long.parseLong(ctx.pathParam("id"));
177	            Reservation reservation = reservationRepository.findById(id)
178	                .orElseThrow(() -> new ValidationException("RESERVATION_NOT_FOUND", "Reservation not found", 404));
179	
180	            ctx.json(toResponse(reservation));
181	
182	        } catch (ValidationException e) {
183	            ctx.status(e.statusCode).json(new ErrorResponse(e.errorCode, e.message));
184	        } catch (NumberFormatException e) {
185	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
186	        }
187	    }
188	
189	    public void confirmReservation(Context ctx) {
190	        try {
191	            Long id = Long.parseLong(ctx.pathParam("id"));
192	            Reservation reservation = reservationRepository.findById(id)
193	                .orElseThrow(() -> new ValidationException("RESERVATION_NOT_FOUND", "Reservation not found", 404));
194	
195	            reservation.confirm();
196	            reservationRepository.update(reservation);
197	
198	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
199	            Document document = documentService.createDocument(reservation, room);
200	            String documentText = documentService.formatDocument(document);
201	            String emailBody = documentService.createConfirmationEmail(reservation.getGuestName(), documentText);
202	
203	            Message message = new Message(
204	                null,
205	                "EMAIL",
206	                reservation.getGuestEmail(),
207	                "Reserva confirmada - Pousada Maré Alta",
208	                emailBody
209	            );
210	            messageRepository.save(message);
211	
212	            ctx.json(toResponse(reservation));
213	
214	        } catch (OperationNotAllowedException e) {
215	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
216	        } catch (ValidationException e) {
217	            ctx.status(e.statusCode).json(new ErrorResponse(e.errorCode, e.message));
218	        } catch (NumberFormatException e) {
219	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
220	        }
221	    }
222	
223	    public void cancelReservation(Context ctx) {
224	        try {
225	            Long id = Long.parseLong(ctx.pathParam("id"));
226	            Reservation reservation = reservationRepository.findById(id)
227	                .orElseThrow(() -> new ValidationException("RESERVATION_NOT_FOUND", "Reservation not found", 404));
228	
229	            reservation.cancel();
230	            reservationRepository.update(reservation);
231	
232	            ctx.json(toResponse(reservation));
233	
234	        } catch (OperationNotAllowedException e) {
235	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
236	        } catch (ValidationException e) {
237	            ctx.status(e.statusCode).json(new ErrorResponse(e.errorCode, e.message));
238	        } catch (NumberFormatException e) {
239	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
240	        }
241	    }
242	
243	    public void checkIn(Context ctx) {
244	        try {
245	            Long id = Long.parseLong(ctx.pathParam("id"));
246	            Reservation reservation = reservationRepository.findById(id)
247	                .orElseThrow(() -> new ValidationException("RESERVATION_NOT_FOUND", "Reservation not found", 404));
248	
249	            reservation.checkIn();
250	            reservationRepository.update(reservation);
251	
252	            ctx.json(toResponse(reservation));
253	
254	        } catch (OperationNotAllowedException e) {
255	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
256	        } catch (ValidationException e) {
257	            ctx.status(e.statusCode).json(new ErrorResponse(e.errorCode, e.message));
258	        } catch (NumberFormatException e) {
259	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
260	        }
261	    }
262	
263	    public void checkOut(Context ctx) {
264	        try {
265	            Long id = Long.parseLong(ctx.pathParam("id"));
266	            Reservation reservation = reservationRepository.findById(id)
267	                .orElseThrow(() -> new ValidationException("RESERVATION_NOT_FOUND", "Reservation not found", 404));
268	
269	            reservation.checkOut();
270	            reservationRepository.update(reservation);
271	
272	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
273	            Document document = documentService.createDocument(reservation, room);
274	
275	            ctx.json(toDocumentResponse(document));
276	
277	        } catch (OperationNotAllowedException e) {
278	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
279	        } catch (ValidationException e) {
280	            ctx.status(e.statusCode).json(new ErrorResponse(e.errorCode, e.message));
281	        } catch (NumberFormatException e) {
282	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
283	        }
284	    }
285	
286	    public void getDocument(Context ctx) {
287	        try {
288	            Long id = Long.parseLong(ctx.pathParam("id"));
289	            Reservation reservation = reservationRepository.findById(id)
290	                .orElseThrow(() -> new ValidationException("RESERVATION_NOT_FOUND", "Reservation not found", 404));
291	
292	            if (!reservation.isPaid()) {
293	                throw new ValidationException("OPERATION_NOT_ALLOWED", "Document is only available for paid reservations", 409);
294	            }
295	
296	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
297	            Document document = documentService.createDocument(reservation, room);
298	
299	            ctx.json(toDocumentResponse(document));
300	
301	        } catch (ValidationException e) {
302	            ctx.status(e.statusCode).json(new ErrorResponse(e.errorCode, e.message));
303	        } catch (NumberFormatException e) {
304	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
305	        }
306	    }
307	
308	    private void validateRequest(CreateReservationRequest request) {
309	        if (request.roomNumber() == null || request.guestName() == null ||
310	            request.guestEmail() == null || request.guestCpf() == null ||
311	            request.checkIn() == null || request.checkOut() == null || request.ratePlan() == null) {
312	            throw new ValidationException("INVALID_REQUEST", "Missing required fields", 400);
313	        }
314	
315	        if (request.guests() < 1) {
316	            throw new ValidationException("INVALID_REQUEST", "Number of guests must be at least 1", 400);
317	        }
318	
319	        if (!request.checkOut().isAfter(request.checkIn())) {
320	            throw new ValidationException("INVALID_REQUEST", "Check-out date must be after check-in date", 400);
321	        }
322	    }
323	
324	    private ReservationResponse toResponse(Reservation reservation) {
325	        return new ReservationResponse(
326	            reservation.getId(),
327	            reservation.getRoomNumber(),
328	            reservation.getGuestName(),
329	            reservation.getGuestEmail(),
330	            reservation.getGuestCpf(),
331	            reservation.getCheckIn(),
332	            reservation.getCheckOut(),
333	            reservation.getGuests(),
334	            reservation.getRatePlan().getName(),
335	            reservation.getNights(),
336	            reservation.getSubtotal(),
337	            reservation.getDiscount(),
338	            reservation.getTotal(),
339	            reservation.getStatus().name(),
340	            reservation.getAmountPaid(),
341	            reservation.getRefund()
342	        );
343	    }
344	
345	    private DocumentResponse toDocumentResponse(Document document) {
346	        return new DocumentResponse(
347	            document.getTitle(),
348	            document.getReservationId(),
349	            document.getGuestName(),
350	            document.getGuestCpf(),
351	            document.getRoomNumber(),
352	            document.getRoomType(),
353	            document.getCheckIn(),
354	            document.getCheckOut(),
355	            document.getNights(),
356	            document.getSubtotal(),
357	            document.getDiscount(),
358	            document.getTotal()
359	        );
360	    }
361	
362	    private static class ValidationException extends RuntimeException {
363	        final String errorCode;
364	        final String message;
365	        final int statusCode;
366	
367	        ValidationException(String errorCode, String message, int statusCode) {
368	            super(message);
369	            this.errorCode = errorCode;
370	            this.message = message;
371	            this.statusCode = statusCode;
372	        }
373	    }
374	}

