 23	    public void initializeSchema() {
 24	        try (Connection conn = getConnection();
 25	             Statement stmt = conn.createStatement()) {
 26	
 27	            stmt.execute("""
 28	                CREATE TABLE IF NOT EXISTS ROOMS (
 29	                    NUMBER VARCHAR(10) PRIMARY KEY,
 30	                    TYPE VARCHAR(20) NOT NULL,
 31	                    CAPACITY INT NOT NULL,
 32	                    NIGHTLY_RATE DECIMAL(10, 2) NOT NULL
 33	                )
 34	                """);
 35	
 36	            stmt.execute("""
 37	                CREATE TABLE IF NOT EXISTS RESERVATIONS (
 38	                    ID BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 39	                    ROOM_NUMBER VARCHAR(10) NOT NULL,
 40	                    GUEST_NAME VARCHAR(255) NOT NULL,
 41	                    GUEST_EMAIL VARCHAR(255) NOT NULL,
 42	                    GUEST_CPF VARCHAR(11) NOT NULL,
 43	                    CHECK_IN DATE NOT NULL,
 44	                    CHECK_OUT DATE NOT NULL,
 45	                    GUESTS INT NOT NULL,
 46	                    RATE_PLAN VARCHAR(20) NOT NULL,
 47	                    NIGHTS INT NOT NULL,
 48	                    SUBTOTAL DECIMAL(10, 2) NOT NULL,
 49	                    DISCOUNT DECIMAL(10, 2) NOT NULL,
 50	                    TOTAL DECIMAL(10, 2) NOT NULL,
 51	                    STATUS VARCHAR(20) NOT NULL,
 52	                    AMOUNT_PAID DECIMAL(10, 2) NOT NULL,
 53	                    REFUND DECIMAL(10, 2),
 54	                    FOREIGN KEY (ROOM_NUMBER) REFERENCES ROOMS(NUMBER)
 55	                )
 56	                """);
 57	
 58	            stmt.execute("""
 59	                CREATE TABLE IF NOT EXISTS MESSAGES (
 60	                    ID BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 61	                    CHANNEL VARCHAR(20) NOT NULL,
 62	                    RECIPIENT VARCHAR(255) NOT NULL,
 63	                    SUBJECT VARCHAR(255) NOT NULL,
 64	                    BODY TEXT NOT NULL
 65	                )
 66	                """);
 67	
 68	        } catch (SQLException e) {
 69	            e.printStackTrace();
 70	            throw new RuntimeException("Failed to initialize database schema", e);
 71	        }
 72	    }
 73	}
