159	
160	public class ReservationRepository {
161	    private final Database database;
162	
163	    public ReservationRepository(Database database) {
164	        this.database = database;
165	    }
166	
167	    public Reservation save(Reservation reservation) {
168	        String sql = """
169	            INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
170	                                     guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
171	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
172	            """;
173	
174	        try (Connection conn = database.getConnection();
175	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
176	
177	            stmt.setString(1, reservation.getRoomNumber());
178	            stmt.setString(2, reservation.getGuestName());
179	            stmt.setString(3, reservation.getGuestEmail());
180	            stmt.setString(4, reservation.getGuestCpf());
181	            stmt.setDate(5, Date.valueOf(reservation.getCheckIn()));
182	            stmt.setDate(6, Date.valueOf(reservation.getCheckOut()));
183	            stmt.setInt(7, reservation.getGuests());
184	            stmt.setString(8, reservation.getRatePlan().getName());
185	            stmt.setInt(9, reservation.getNights());
186	            stmt.setBigDecimal(10, reservation.getSubtotal());
187	            stmt.setBigDecimal(11, reservation.getDiscount());
188	            stmt.setBigDecimal(12, reservation.getTotal());
189	            stmt.setString(13, reservation.getStatus().name());
190	            stmt.setBigDecimal(14, reservation.getAmountPaid());
191	
192	            if (reservation.getRefund() != null) {
193	                stmt.setBigDecimal(15, reservation.getRefund());
194	            } else {
195	                stmt.setNull(15, Types.DECIMAL);
196	            }
197	
198	            stmt.executeUpdate();
199	
200	            try (ResultSet rs = stmt.getGeneratedKeys()) {
201	                if (rs.next()) {
202	                    reservation.setId(rs.getLong(1));
203	                }
204	            }
205	
206	        } catch (SQLException e) {
207	            throw new RuntimeException("Failed to save reservation", e);
208	        }
209	
210	        return reservation;
211	    }
212	
213	    public void update(Reservation reservation) {
214	        String sql = """
215	            UPDATE reservations
216	            SET status = ?, amount_paid = ?, refund = ?
217	            WHERE id = ?
218	            """;
219	
220	        try (Connection conn = database.getConnection();
221	             PreparedStatement stmt = conn.prepareStatement(sql)) {
222	
223	            stmt.setString(1, reservation.getStatus().name());
224	            stmt.setBigDecimal(2, reservation.getAmountPaid());
225	
226	            if (reservation.getRefund() != null) {
227	                stmt.setBigDecimal(3, reservation.getRefund());
228	            } else {
229	                stmt.setNull(3, Types.DECIMAL);
230	            }
231	
232	            stmt.setLong(4, reservation.getId());
233	            stmt.executeUpdate();
234	
235	        } catch (SQLException e) {
236	            throw new RuntimeException("Failed to update reservation", e);
237	        }
238	    }
239	
240	    public Optional<Reservation> findById(Long id) {
241	        String sql = """
242	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
243	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
244	            FROM reservations
245	            WHERE id = ?
246	            """;
247	
248	        try (Connection conn = database.getConnection();
249	             PreparedStatement stmt = conn.prepareStatement(sql)) {
250	
251	            stmt.setLong(1, id);
252	
253	            try (ResultSet rs = stmt.executeQuery()) {
254	                if (rs.next()) {
255	                    return Optional.of(mapReservation(rs));
256	                }
257	            }
258	
259	        } catch (SQLException e) {
260	            throw new RuntimeException("Failed to find reservation", e);
261	        }
262	
263	        return Optional.empty();
264	    }
