266	    public boolean hasConflict(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeReservationId) {
267	        String sql = """
268	            SELECT COUNT(*) FROM reservations
269	            WHERE room_number = ?
270	              AND status != 'CANCELLED'
271	              AND check_in < ?
272	              AND check_out > ?
273	              AND (? IS NULL OR id != ?)
274	            """;
275	
276	        try (Connection conn = database.getConnection();
277	             PreparedStatement stmt = conn.prepareStatement(sql)) {
278	
279	            stmt.setString(1, roomNumber);
280	            stmt.setDate(2, Date.valueOf(checkOut));
281	            stmt.setDate(3, Date.valueOf(checkIn));
282	
283	            if (excludeReservationId != null) {
284	                stmt.setLong(4, excludeReservationId);
285	                stmt.setLong(5, excludeReservationId);
286	            } else {
287	                stmt.setNull(4, Types.BIGINT);
288	                stmt.setNull(5, Types.BIGINT);
289	            }
290	
291	            try (ResultSet rs = stmt.executeQuery()) {
292	                if (rs.next()) {
293	                    return rs.getInt(1) > 0;
294	                }
295	            }
296	
297	        } catch (SQLException e) {
298	            throw new RuntimeException("Failed to check room availability", e);
299	        }
300	
301	        return false;
302	    }
303	
304	    public List<Reservation> findPaidReservationsForNight(LocalDate date) {
305	        String sql = """
306	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
307	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
308	            FROM reservations
309	            WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
310	              AND check_in <= ?
311	              AND check_out > ?
312	            ORDER BY room_number
313	            """;
314	
315	        return executeQuery(sql, stmt -> {
316	            stmt.setDate(1, Date.valueOf(date));
317	            stmt.setDate(2, Date.valueOf(date));
318	        });
319	    }
320	
321	    public List<Reservation> findReservationsStartingInMonth(int year, int month) {
322	        LocalDate startOfMonth = LocalDate.of(year, month, 1);
323	        LocalDate startOfNextMonth = startOfMonth.plusMonths(1);
324	
325	        String sql = """
326	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
327	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
328	            FROM reservations
329	            WHERE check_in >= ? AND check_in < ?
330	            ORDER BY check_in, id
331	            """;
332	
333	        return executeQuery(sql, stmt -> {
334	            stmt.setDate(1, Date.valueOf(startOfMonth));
335	            stmt.setDate(2, Date.valueOf(startOfNextMonth));
336	        });
337	    }
338	
339	    private List<Reservation> executeQuery(String sql, StatementPreparer preparer) {
340	        List<Reservation> reservations = new ArrayList<>();
341	
342	        try (Connection conn = database.getConnection();
343	             PreparedStatement stmt = conn.prepareStatement(sql)) {
344	
345	            preparer.prepare(stmt);
346	
347	            try (ResultSet rs = stmt.executeQuery()) {
348	                while (rs.next()) {
349	                    reservations.add(mapReservation(rs));
350	                }
351	            }
352	
353	        } catch (SQLException e) {
354	            throw new RuntimeException("Failed to execute query", e);
355	        }
356	
357	        return reservations;
358	    }
359	
360	    private Reservation mapReservation(ResultSet rs) throws SQLException {
361	        Long id = rs.getLong("id");
362	        String roomNumber = rs.getString("room_number");
363	        String guestName = rs.getString("guest_name");
364	        String guestEmail = rs.getString("guest_email");
365	        String guestCpf = rs.getString("guest_cpf");
366	        LocalDate checkIn = rs.getDate("check_in").toLocalDate();
367	        LocalDate checkOut = rs.getDate("check_out").toLocalDate();
368	        int guests = rs.getInt("guests");
369	        RatePlan ratePlan = RatePlanFactory.get(rs.getString("rate_plan"));
370	        int nights = rs.getInt("nights");
371	        var subtotal = rs.getBigDecimal("subtotal");
372	        var discount = rs.getBigDecimal("discount");
373	        var total = rs.getBigDecimal("total");
374	        ReservationStatus status = ReservationStatus.valueOf(rs.getString("status"));
375	        var amountPaid = rs.getBigDecimal("amount_paid");
376	        var refund = rs.getBigDecimal("refund");
377	
378	        Reservation reservation = new Reservation(
379	            id, roomNumber, guestName, guestEmail, guestCpf,
380	            checkIn, checkOut, guests, ratePlan,
381	            nights, subtotal, discount, total
382	        );
383	
384	        reservation.setState(ReservationStateFactory.create(status));
385	        reservation.setAmountPaid(amountPaid);
386	        reservation.setRefund(refund);
387	
388	        return reservation;
389	    }
390	
391	    @FunctionalInterface
392	    private interface StatementPreparer {
393	        void prepare(PreparedStatement stmt) throws SQLException;
394	    }
395	}
