 83	public class RatePlansReport extends Report {
 84	    private final int year;
 85	    private final int month;
 86	    private final ReservationRepository reservationRepository;
 87	    private Map<String, PlanStats> planStats;
 88	    private int totalReservations;
 89	    private BigDecimal totalAmount;
 90	
 91	    public RatePlansReport(int year, int month, ReservationRepository reservationRepository) {
 92	        this.year = year;
 93	        this.month = month;
 94	        this.reservationRepository = reservationRepository;
 95	    }
 96	
 97	    @Override
 98	    protected String getReportName() {
 99	        return "rate-plans";
100	    }
101	
102	    @Override
103	    protected String getPeriod() {
104	        return String.format("%04d-%02d", year, month);
105	    }
106	
107	    @Override
108	    protected String buildHeaderLine() {
109	        return "rate_plan,reservations,amount";
110	    }
111	
112	    @Override
113	    protected List<String> buildDataLines() {
114	        planStats = new LinkedHashMap<>();
115	
116	        for (Map.Entry<String, RatePlan> entry : RatePlanFactory.getAll().entrySet()) {
117	            planStats.put(entry.getKey(), new PlanStats());
118	        }
119	
120	        List<Reservation> reservations = reservationRepository.findReservationsStartingInMonth(year, month);
121	
122	        for (Reservation reservation : reservations) {
123	            BigDecimal revenue = calculateRevenue(reservation);
124	            PlanStats stats = planStats.get(reservation.getRatePlan().getName());
125	            stats.count++;
126	            stats.amount = stats.amount.add(revenue);
127	        }
128	
129	        totalReservations = 0;
130	        totalAmount = BigDecimal.ZERO;
131	
132	        List<String> lines = new ArrayList<>();
133	        for (Map.Entry<String, PlanStats> entry : planStats.entrySet()) {
134	            PlanStats stats = entry.getValue();
135	            totalReservations += stats.count;
136	            totalAmount = totalAmount.add(stats.amount);
137	
138	            lines.add(String.join(",",
139	                entry.getKey(),
140	                String.valueOf(stats.count),
141	                formatAmount(stats.amount)
142	            ));
143	        }
144	
145	        return lines;
146	    }
147	
148	    @Override
149	    protected String buildTotalLine() {
150	        return String.format("total,%d,%s", totalReservations, formatAmount(totalAmount));
151	    }
152	
153	    private BigDecimal calculateRevenue(Reservation reservation) {
154	        BigDecimal paid = reservation.getAmountPaid();
155	        BigDecimal refunded = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
156	        return paid.subtract(refunded);
157	    }
158	
159	    private String formatAmount(BigDecimal amount) {
160	        return amount.toString();
161	    }
162	
163	    private static class PlanStats {
164	        int count = 0;
165	        BigDecimal amount = BigDecimal.ZERO;
166	    }
167	}
