687	public class PricingService {
688	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
689	    private static final int HIGH_SEASON_START_MONTH = 12;
690	    private static final int HIGH_SEASON_START_DAY = 15;
691	    private static final int HIGH_SEASON_END_MONTH = 2;
692	    private static final int HIGH_SEASON_JULY_MONTH = 7;
693	
694	    public BigDecimal calculateSubtotal(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut) {
695	        BigDecimal subtotal = BigDecimal.ZERO;
696	        LocalDate currentDate = checkIn;
697	
698	        while (currentDate.isBefore(checkOut)) {
699	            BigDecimal nightPrice = nightlyRate;
700	            if (isHighSeason(currentDate)) {
701	                nightPrice = nightPrice.multiply(HIGH_SEASON_MULTIPLIER)
702	                    .setScale(2, RoundingMode.HALF_EVEN);
703	            }
704	            subtotal = subtotal.add(nightPrice);
705	            currentDate = currentDate.plusDays(1);
706	        }
707	
708	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
709	    }
710	
711	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
712	        return ratePlan.calculateDiscount(subtotal);
713	    }
714	
715	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
716	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
717	    }
718	
719	    private boolean isHighSeason(LocalDate date) {
720	        int month = date.getMonthValue();
721	        int day = date.getDayOfMonth();
722	
723	        if (month == HIGH_SEASON_JULY_MONTH) {
724	            return true;
725	        }
726	
727	        if (month == HIGH_SEASON_START_MONTH && day >= HIGH_SEASON_START_DAY) {
728	            return true;
729	        }
730	
731	        if (month == 1 || month == HIGH_SEASON_END_MONTH) {
732	            return true;
733	        }
734	
735	        return false;
736	    }
737	}

